/**
 * Audio Analysis view (TPI-V2-WEB-010 §8/§9/§22, Phase 010B).
 *
 * Presents the confirmed original feature set from
 * `Core/Audio/PPAudioAnalysisCoordinator.swift`: waveform, playback with
 * timeline navigation, selection, gain/filter operations, spectrum,
 * spectrogram, anomaly candidates, analyst notes and derived saves.
 *
 * Integrity: the decoded source is never mutated. Every edit works on a copy;
 * "Save Derivative" writes a NEW evidence item that references the source.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import {
  ANOMALY_DEFAULT_MIN_SPACING_S,
  ANOMALY_DEFAULT_THRESHOLD_DB,
  AudioAnalysisSession,
  loadAudioForAnalysis,
  type LoadedAudio,
} from "../../core/media/audioAnalysis";
import type { EvidenceRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { navigate } from "../../app/router";

const db = () => getDb();

interface AnalysisUiState {
  evidenceId: string | null;
  session: AudioAnalysisSession | null;
  source: EvidenceRecord | null;
  selection: { start: number; end: number } | null;
  notes: string;
  /** Derivative bit depth — original ExportOptions supports 8/16/24/32. */
  bitDepth: 8 | 16 | 24 | 32;
  status: string;
  anomalyThreshold: number;
  anomalyMinSpacing: number;
  anomalies: number[];
  gainDB: number;
  lowGain: number;
  midGain: number;
  highGain: number;
  noiseAmount: number;
  speedFactor: number;
  /** Object URLs created for playback; revoked on re-render. */
  objectUrls: string[];
}

const ui = new WeakMap<HTMLElement, AnalysisUiState>();

function st(container: HTMLElement): AnalysisUiState {
  let s = ui.get(container);
  if (!s) {
    s = {
      evidenceId: null,
      session: null,
      source: null,
      selection: null,
      notes: "",
      bitDepth: 16,
      status: "Select an audio item to analyse.",
      anomalyThreshold: ANOMALY_DEFAULT_THRESHOLD_DB,
      anomalyMinSpacing: ANOMALY_DEFAULT_MIN_SPACING_S,
      anomalies: [],
      gainDB: 6,
      lowGain: 1,
      midGain: 1,
      highGain: 1,
      noiseAmount: 0.5,
      speedFactor: 1,
      objectUrls: [],
    };
    ui.set(container, s);
  }
  return s;
}

function fmtTime(seconds: number): string {
  const total = Math.max(0, seconds);
  return `${String(Math.floor(total / 60)).padStart(2, "0")}:${(total % 60).toFixed(2).padStart(5, "0")}`;
}

/** Release playback object URLs from the previous render. */
function releaseUrls(s: AnalysisUiState): void {
  for (const url of s.objectUrls) URL.revokeObjectURL(url);
  s.objectUrls = [];
}

export async function renderAudioAnalysis(container: HTMLElement, evidenceId?: string): Promise<void> {
  const s = st(container);
  if (evidenceId) s.evidenceId = evidenceId;

  // Candidate audio items across cases (audio originals).
  const allAudio = (await db().evidence.toArray()).filter((e) => e.mediaType === "audio" && e.kind === "original");
  allAudio.sort((a, b) => b.createdAt - a.createdAt);
  if (!s.evidenceId && allAudio.length > 0) s.evidenceId = allAudio[0]!.id;

  // Load the selected item into an analysis session (once per selection).
  if (s.evidenceId && s.source?.id !== s.evidenceId) {
    s.session = null;
    s.anomalies = [];
    s.selection = null;
    s.status = "Loading audio…";
    const record = await db().evidence.get(s.evidenceId);
    s.source = record ?? null;
    if (record) {
      try {
        const { getManagedFileStore } = await import("../../core/files/storeRegistry");
        const bytes = await getManagedFileStore().read(record.opfsPath);
        if (!bytes) {
          s.status = "The managed copy is not present in browser storage, so analysis is unavailable.";
        } else {
          const loaded: LoadedAudio = await loadAudioForAnalysis(
            new File([bytes], record.originalFileName ?? record.fileName, { type: record.mimeType ?? "" }),
          );
          s.session = new AudioAnalysisSession(loaded);
          s.status = `Loaded ${loaded.fileName} — ${loaded.sampleRate} Hz, ${fmtTime(loaded.durationSeconds)}, ${loaded.channels === 1 ? "mono" : `${loaded.channels} ch`} (analysed as mono).`;
        }
      } catch (err) {
        s.status = `Audio could not be decoded for analysis: ${(err as Error).message}`;
      }
    }
  }

  const session = s.session;
  releaseUrls(s);

  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Audio Analysis",
      `
      <div class="case-form" data-root="audio-analysis" data-epoch="${Date.now()}-${Math.random()}">
        <h3 class="cc-section-title">Source Recording</h3>
        <div class="detail-field"><label for="aa-source">Audio evidence</label>
          <select id="aa-source">
            ${allAudio.length === 0 ? '<option value="">— no audio evidence yet —</option>' : allAudio.map((e) => `<option value="${e.id}"${e.id === s.evidenceId ? " selected" : ""}>${esc(e.title)} — ${esc(e.originalFileName ?? e.fileName)}</option>`).join("")}
          </select></div>
        <p class="cc-count" role="status">${esc(s.status)}</p>
        ${
          s.source
            ? `<div class="case-row"><div>
                 <div class="case-title">${esc(s.source.title)} ${session?.isModified ? '<span class="status-badge pending">MODIFIED COPY</span>' : '<span class="status-badge implemented">ORIGINAL</span>'}</div>
                 <div class="case-meta">SHA-256 ${esc(s.source.contentHash.slice(0, 24))}… • integrity ${esc(s.source.verificationStatus ?? "unverified")} • captured ${new Date(s.source.captureTimestamp ?? s.source.acquiredAt).toLocaleString()}</div>
               </div></div>`
            : ""
        }
        <p class="cc-meta">Analysis always operates on an in-memory copy. The original recording is never modified; saved results are separate derivatives.</p>

        ${
          session
            ? `
        <h3 class="cc-section-title">Waveform</h3>
        <canvas id="aa-waveform" width="900" height="160" style="width:100%;background:#0B0E12;border:1px solid #2A3441;border-radius:8px;" aria-label="Waveform"></canvas>
        <div class="case-meta" id="aa-selection-label">Selection: none — drag across the waveform to select a range.</div>

        <h3 class="cc-section-title">Playback</h3>
        <div id="aa-player">${playerHtml(s, session)}</div>
        <div class="form-actions">
          <button class="back-button" id="aa-select-all" type="button">Select All</button>
          <button class="back-button" id="aa-clear-selection" type="button">Clear Selection</button>
          <button class="back-button" id="aa-prev-anomaly" type="button">◀ Previous Anomaly</button>
          <button class="back-button" id="aa-next-anomaly" type="button">Next Anomaly ▶</button>
        </div>

        <h3 class="cc-section-title">Edit Operations</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="aa-gain">Amplify (dB)</label><input id="aa-gain" type="number" step="0.5" value="${s.gainDB}"></div>
          <div class="detail-field"><label for="aa-speed">Speed ×</label><input id="aa-speed" type="number" step="0.05" min="0.05" value="${s.speedFactor}"></div>
          <div class="detail-field"><label for="aa-noise">Noise reduction (0–1)</label><input id="aa-noise" type="number" step="0.05" min="0" max="1" value="${s.noiseAmount}"></div>
        </div>
        <div class="detail-grid">
          <div class="detail-field"><label for="aa-low">Equalizer low (&lt;250 Hz)</label><input id="aa-low" type="number" step="0.1" value="${s.lowGain}"></div>
          <div class="detail-field"><label for="aa-mid">Equalizer mid</label><input id="aa-mid" type="number" step="0.1" value="${s.midGain}"></div>
          <div class="detail-field"><label for="aa-high">Equalizer high (&gt;2500 Hz)</label><input id="aa-high" type="number" step="0.1" value="${s.highGain}"></div>
        </div>
        <div class="form-actions">
          <button class="button-secondary" id="aa-cut" type="button">Cut</button>
          <button class="button-secondary" id="aa-copy" type="button">Copy</button>
          <button class="button-secondary" id="aa-paste" type="button">Paste</button>
          <button class="button-secondary" id="aa-delete" type="button">Delete</button>
          <button class="button-secondary" id="aa-reverse" type="button">Reverse</button>
          <button class="button-secondary" id="aa-amplify" type="button">Amplify</button>
          <button class="button-secondary" id="aa-normalize" type="button">Normalize</button>
          <button class="button-secondary" id="aa-equalizer" type="button">Equalizer</button>
          <button class="button-secondary" id="aa-denoiser" type="button">Reduce Noise</button>
          <button class="button-secondary" id="aa-speed-apply" type="button">Change Speed</button>
          <button class="button-secondary" id="aa-undo" type="button" ${session.canUndo() ? "" : "disabled"}>Undo</button>
          <button class="button-secondary" id="aa-redo" type="button" ${session.canRedo() ? "" : "disabled"}>Redo</button>
          <button class="back-button" id="aa-reset" type="button">Reset to Original</button>
        </div>

        <h3 class="cc-section-title">Spectrum (2048 FFT)</h3>
        <canvas id="aa-spectrum" width="900" height="150" style="width:100%;background:#0B0E12;border:1px solid #2A3441;border-radius:8px;" aria-label="Magnitude spectrum"></canvas>
        <div class="case-meta" id="aa-top-freq">—</div>

        <h3 class="cc-section-title">Spectrogram (2048 FFT, 75% overlap, 20 Hz–12 kHz, −80…0 dB)</h3>
        <canvas id="aa-spectrogram" width="900" height="280" style="width:100%;background:#0B0E12;border:1px solid #2A3441;border-radius:8px;" aria-label="Spectrogram"></canvas>

        <h3 class="cc-section-title">Segment Review — Anomaly Candidates</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="aa-threshold">Threshold (dBFS)</label><input id="aa-threshold" type="number" step="1" value="${s.anomalyThreshold}"></div>
          <div class="detail-field"><label for="aa-spacing">Minimum spacing (s)</label><input id="aa-spacing" type="number" step="0.05" value="${s.anomalyMinSpacing}"></div>
        </div>
        <div class="form-actions"><button class="button-secondary" id="aa-detect" type="button">Detect Candidates</button></div>
        <p class="cc-meta">This is a <strong>threshold detector on the real samples</strong> — it flags loud/abrupt moments for review. It is not a classifier, it does not identify voices or words, and it makes no claim about paranormal activity. No transcript is generated.</p>
        <div id="aa-anomalies">${s.anomalies.length === 0 ? '<div class="cc-empty">No candidates detected yet.</div>' : s.anomalies.map((t) => `<div class="case-row"><div><div class="case-title">${fmtTime(t)}</div><div class="case-meta">Portion of the recording at or above ${s.anomalyThreshold} dBFS</div></div><button class="back-button" data-goto="${t}" type="button">Play from here</button></div>`).join("")}</div>

        <h3 class="cc-section-title">Save Processed Result</h3>
        <div class="detail-field"><label for="aa-bitdepth">Derivative bit depth (original options: 8 / 16 / 24 / 32)</label>
          <select id="aa-bitdepth">
            ${([8, 16, 24, 32] as const).map((b) => `<option value="${b}"${b === s.bitDepth ? " selected" : ""}>${b}-bit PCM WAV</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="aa-notes">Analyst notes (saved with the derivative)</label>
          <textarea id="aa-notes" rows="2" placeholder="What did you examine and what did you conclude?">${esc(s.notes)}</textarea></div>
        <div class="form-actions">
          <button class="button-primary" id="aa-save-derivative" type="button">Save Processed Copy to Case</button>
          <button class="button-secondary" id="aa-save-selection" type="button" ${s.selection ? "" : "disabled"}>Save Selection to Case</button>
        </div>
        <p class="cc-meta">Saved results are <strong>derivatives</strong>: they reference this source recording, record the operations and parameters, and carry their own SHA-256 digest. The original stays untouched and is listed separately in the evidence library.</p>

        <h3 class="cc-section-title">Operation Log (${session.operationLog.length})</h3>
        ${session.operationLog.length === 0
          ? '<div class="cc-empty">No operations applied.</div>'
          : session.operationLog
              .map((op) => `<div class="case-row"><div><div class="case-title">${esc(op.kind)}</div><div class="case-meta">${new Date(op.timestamp).toLocaleTimeString()} • ${esc(op.note)}</div></div></div>`)
              .join("")}
        `
            : ""
        }

        <div class="form-actions"><button class="back-button" id="aa-back" type="button">← Back</button></div>
      </div>
    `,
  ));

  if (session) {
    drawWaveform(container, s);
    drawSpectrum(container, s);
    drawSpectrogram(container, s);
    wireWaveformSelection(container, s);
  }
  wireHandlers(container, s);
  wireBackButton(container);
}

function playerHtml(s: AnalysisUiState, session: AudioAnalysisSession): string {
  if (!s.source) return '<div class="cc-empty">No source.</div>';
  return `
    <audio id="aa-audio" controls style="width:100%" src="${objectUrlFor(s, session.currentSamples, session.sampleRate)}" aria-label="Analysis playback"></audio>
    <p class="cc-meta">Playback uses the ${session.isModified ? "modified in-memory copy" : "original in-memory copy"} at ${session.sampleRate} Hz.</p>`;
}

function objectUrlFor(s: AnalysisUiState, samples: Float32Array, sampleRate: number): string {
  // Build a WAV for playback from the in-memory samples (never persisted here).
  const wav = encodeWavForPlayback(samples, sampleRate);
  const url = URL.createObjectURL(new Blob([wav], { type: "audio/wav" }));
  s.objectUrls.push(url);
  return url;
}

function encodeWavForPlayback(samples: Float32Array, sampleRate: number): ArrayBuffer {
  const dataBytes = samples.length * 2;
  const buffer = new ArrayBuffer(44 + dataBytes);
  const view = new DataView(buffer);
  let o = 0;
  const ascii = (str: string) => {
    for (const ch of str) view.setUint8(o++, ch.charCodeAt(0));
  };
  const u16 = (v: number) => {
    view.setUint16(o, v, true);
    o += 2;
  };
  const u32 = (v: number) => {
    view.setUint32(o, v, true);
    o += 4;
  };
  ascii("RIFF");
  u32(36 + dataBytes);
  ascii("WAVE");
  ascii("fmt ");
  u32(16);
  u16(1);
  u16(1);
  u32(sampleRate);
  u32(sampleRate * 2);
  u16(2);
  u16(16);
  ascii("data");
  u32(dataBytes);
  for (let i = 0; i < samples.length; i += 1) {
    const v = Math.max(-1, Math.min(1, samples[i] ?? 0));
    view.setInt16(o, v < 0 ? v * 0x8000 : v * 0x7fff, true);
    o += 2;
  }
  return buffer;
}

/* ------------------------------- rendering -------------------------------- */

function drawWaveform(container: HTMLElement, s: AnalysisUiState): void {
  const canvas = container.querySelector<HTMLCanvasElement>("#aa-waveform");
  const session = s.session;
  if (!canvas || !session) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);

  const bins = session.waveformDB(900);
  const mid = h / 2;
  // Baseline
  ctx.strokeStyle = "#1C2630";
  ctx.beginPath();
  ctx.moveTo(0, mid);
  ctx.lineTo(w, mid);
  ctx.stroke();
  // Envelope (dBFS → height, -80…0 range as in the original)
  ctx.fillStyle = "#00C2FF";
  for (let i = 0; i < bins.length; i += 1) {
    const db = Math.max(-80, Math.min(0, bins[i] ?? -80));
    const amp = ((db + 80) / 80) * (h / 2 - 4);
    ctx.fillRect(i, mid - amp, 1, amp * 2 || 1);
  }
  // Selection overlay
  if (s.selection) {
    const dur = session.duration || 1;
    const x1 = (s.selection.start / dur) * w;
    const x2 = (s.selection.end / dur) * w;
    ctx.fillStyle = "rgba(0, 194, 255, 0.16)";
    ctx.fillRect(x1, 0, Math.max(1, x2 - x1), h);
    ctx.strokeStyle = "#00C2FF";
    ctx.strokeRect(x1, 0, Math.max(1, x2 - x1), h);
  }
  // Anomaly markers
  if (s.anomalies.length > 0) {
    const dur = session.duration || 1;
    ctx.strokeStyle = "#E0A83C";
    for (const t of s.anomalies) {
      const x = (t / dur) * w;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
  }
  const label = container.querySelector<HTMLElement>("#aa-selection-label");
  if (label) {
    label.textContent = s.selection
      ? `Selection: ${fmtTime(s.selection.start)} → ${fmtTime(s.selection.end)} (${(s.selection.end - s.selection.start).toFixed(2)}s, peak ${session.peakDBFSIn(s.selection.start, s.selection.end).toFixed(1)} dBFS)`
      : "Selection: none — drag across the waveform to select a range.";
  }
}

function drawSpectrum(container: HTMLElement, s: AnalysisUiState): void {
  const canvas = container.querySelector<HTMLCanvasElement>("#aa-spectrum");
  const session = s.session;
  if (!canvas || !session) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const at = s.selection?.start ?? 0;
  const mags = session.spectrumSnapshot(at);
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#00C2FF";
  for (let i = 0; i < mags.length; i += 1) {
    const db = Math.max(-100, Math.min(0, mags[i] ?? -100));
    const y = ((db + 100) / 100) * h;
    ctx.fillRect((i / mags.length) * w, h - y, Math.max(1, w / mags.length), y);
  }
  const top = session.spectrumTopFrequencies(at, 6);
  const label = container.querySelector<HTMLElement>("#aa-top-freq");
  if (label) {
    label.textContent =
      top.length === 0
        ? "—"
        : `Strongest bins at ${fmtTime(at)}: ${top.map((t) => `${Math.round(t.freq)} Hz (${t.magnitude.toFixed(1)} dB)`).join(", ")}`;
  }
}

function drawSpectrogram(container: HTMLElement, s: AnalysisUiState): void {
  const canvas = container.querySelector<HTMLCanvasElement>("#aa-spectrogram");
  const session = s.session;
  if (!canvas || !session) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const spec = session.spectrogramSnapshot();
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);
  const cellW = w / Math.max(1, spec.frames);
  const cellH = h / spec.bins;
  for (let bin = 0; bin < spec.bins; bin += 1) {
    const row = spec.data[bin]!;
    for (let f = 0; f < spec.frames; f += 1) {
      const db = row[f] ?? spec.minDB;
      const t = Math.max(0, Math.min(1, (db - spec.minDB) / (spec.maxDB - spec.minDB)));
      // Cyan → amber → white ramp for readability on the dark theme.
      const r = Math.round(255 * Math.min(1, t * 1.6));
      const g = Math.round(255 * Math.min(1, Math.max(0, t * 1.2 - 0.1)));
      const b = Math.round(255 * Math.min(1, 0.35 + t * 0.65));
      ctx.fillStyle = `rgb(${r},${g},${b})`;
      // Row 0 is the lowest frequency; draw bottom-up.
      ctx.fillRect(f * cellW, h - (bin + 1) * cellH, Math.ceil(cellW), Math.ceil(cellH));
    }
  }
}

/** Drag on the waveform to set the selection range (keyboard alternative exists). */
function wireWaveformSelection(container: HTMLElement, s: AnalysisUiState): void {
  const canvas = container.querySelector<HTMLCanvasElement>("#aa-waveform");
  if (!canvas) return;
  let dragging = false;
  let anchor = 0;
  const timeAt = (clientX: number): number => {
    const rect = canvas.getBoundingClientRect();
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    return ratio * (s.session?.duration ?? 0);
  };
  canvas.addEventListener("pointerdown", (e) => {
    dragging = true;
    anchor = timeAt(e.clientX);
    s.selection = { start: anchor, end: anchor };
    drawWaveform(container, s);
  });
  canvas.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const now = timeAt(e.clientX);
    s.selection = { start: Math.min(anchor, now), end: Math.max(anchor, now) };
    drawWaveform(container, s);
  });
  window.addEventListener("pointerup", () => {
    if (!dragging) return;
    dragging = false;
    if (s.selection && s.selection.end - s.selection.start < 0.01) s.selection = null;
    drawWaveform(container, s);
    drawSpectrum(container, s);
  });
}

function wireHandlers(container: HTMLElement, s: AnalysisUiState): void {
  const reload = () => renderAudioAnalysis(container, s.evidenceId ?? undefined);
  const session = () => s.session;

  onDelegate(container, "click", "#aa-back", () => navigate("forensic"));
  onDelegate(container, "change", "#aa-source", (el) => {
    s.evidenceId = (el as HTMLSelectElement).value || null;
    void reload();
  });

  const selectAll = () => {
    if (!session()) return;
    s.selection = { start: 0, end: session()!.duration };
    void reload();
  };
  onDelegate(container, "click", "#aa-select-all", selectAll);
  onDelegate(container, "click", "#aa-clear-selection", () => {
    s.selection = null;
    void reload();
  });

  onDelegate(container, "click", "[data-goto]", (el) => {
    const t = Number(el.dataset.goto ?? "0");
    const audio = container.querySelector<HTMLAudioElement>("#aa-audio");
    if (audio) {
      audio.currentTime = t;
      void audio.play().catch(() => undefined);
    }
  });
  onDelegate(container, "click", "#aa-next-anomaly", () => {
    const audio = container.querySelector<HTMLAudioElement>("#aa-audio");
    const next = s.anomalies.find((t) => audio && t > audio.currentTime + 0.05) ?? s.anomalies[0];
    if (audio && next !== undefined) {
      audio.currentTime = next;
      void audio.play().catch(() => undefined);
    }
  });
  onDelegate(container, "click", "#aa-prev-anomaly", () => {
    const audio = container.querySelector<HTMLAudioElement>("#aa-audio");
    const before = s.anomalies.filter((t) => audio && t < audio.currentTime - 0.05);
    const prev = before[before.length - 1] ?? s.anomalies[s.anomalies.length - 1];
    if (audio && prev !== undefined) {
      audio.currentTime = prev;
      void audio.play().catch(() => undefined);
    }
  });

  const readNumber = (id: string, fallback: number): number => {
    const v = Number(container.querySelector<HTMLInputElement>(id)?.value ?? "");
    return Number.isFinite(v) ? v : fallback;
  };
  const range = () => (s.selection ? { start: s.selection.start, end: s.selection.end } : { start: null, end: null });

  const runOperation = (fn: (sess: AudioAnalysisSession) => boolean) => {
    const sess = session();
    if (!sess) return;
    const ok = fn(sess);
    s.status = ok ? "Operation applied to the in-memory copy." : "Operation could not be applied (check the selection).";
    void reload();
  };

  onDelegate(container, "click", "#aa-cut", () => {
    const r = range();
    if (!s.selection) {
      s.status = "Select a range on the waveform before cutting.";
      void reload();
      return;
    }
    runOperation((sess) => sess.cut(r.start as number, r.end as number));
  });
  onDelegate(container, "click", "#aa-copy", () => {
    if (!s.selection) {
      s.status = "Select a range before copying.";
      void reload();
      return;
    }
    const ok = session()?.copy(s.selection.start, s.selection.end) ?? false;
    s.status = ok ? "Selection copied." : "Copy failed.";
    void reload();
  });
  onDelegate(container, "click", "#aa-paste", () => {
    runOperation((sess) => sess.paste(s.selection?.start ?? 0));
  });
  onDelegate(container, "click", "#aa-delete", () => {
    if (!s.selection) {
      s.status = "Select a range before deleting.";
      void reload();
      return;
    }
    runOperation((sess) => sess.delete(s.selection!.start, s.selection!.end));
  });
  onDelegate(container, "click", "#aa-reverse", () => {
    const r = range();
    runOperation((sess) => sess.reverse(r.start, r.end));
  });
  onDelegate(container, "click", "#aa-amplify", () => {
    s.gainDB = readNumber("#aa-gain", 6);
    const r = range();
    runOperation((sess) => sess.applyAmplify(s.gainDB, r.start, r.end));
  });
  onDelegate(container, "click", "#aa-normalize", () => {
    const r = range();
    runOperation((sess) => sess.applyNormalize(0.95, r.start, r.end));
  });
  onDelegate(container, "click", "#aa-equalizer", () => {
    s.lowGain = readNumber("#aa-low", 1);
    s.midGain = readNumber("#aa-mid", 1);
    s.highGain = readNumber("#aa-high", 1);
    const r = range();
    runOperation((sess) => sess.applyEqualizer(s.lowGain, s.midGain, s.highGain, r.start, r.end));
  });
  onDelegate(container, "click", "#aa-denoiser", () => {
    s.noiseAmount = readNumber("#aa-noise", 0.5);
    const r = range();
    runOperation((sess) => sess.applyNoiseReduction(s.noiseAmount, r.start, r.end));
  });
  onDelegate(container, "click", "#aa-speed-apply", () => {
    s.speedFactor = readNumber("#aa-speed", 1);
    if (s.speedFactor <= 0.05) {
      s.status = "Speed factor must be greater than 0.05.";
      void reload();
      return;
    }
    const r = range();
    runOperation((sess) => sess.applySpeed(s.speedFactor, r.start, r.end));
  });
  onDelegate(container, "click", "#aa-undo", () => runOperation((sess) => sess.undo()));
  onDelegate(container, "click", "#aa-redo", () => runOperation((sess) => sess.redo()));
  onDelegate(container, "click", "#aa-reset", () => runOperation((sess) => {
    sess.clearOperations();
    return true;
  }));

  onDelegate(container, "click", "#aa-detect", () => {
    const sess = session();
    if (!sess) return;
    s.anomalyThreshold = readNumber("#aa-threshold", ANOMALY_DEFAULT_THRESHOLD_DB);
    s.anomalyMinSpacing = readNumber("#aa-spacing", ANOMALY_DEFAULT_MIN_SPACING_S);
    s.anomalies = sess.detectAnomalies(s.anomalyThreshold, s.anomalyMinSpacing);
    s.status = `${s.anomalies.length} candidate segment(s) at or above ${s.anomalyThreshold} dBFS.`;
    void reload();
  });

  const saveDerivative = async (selectionOnly: boolean) => {
    const sess = session();
    if (!sess || !s.source) return;
    const caseId = s.source.caseId;
    const notes = container.querySelector<HTMLTextAreaElement>("#aa-notes")?.value ?? s.notes;
    s.notes = notes;
    s.bitDepth = (Number(container.querySelector<HTMLSelectElement>("#aa-bitdepth")?.value ?? "16") as 8 | 16 | 24 | 32) || 16;
    const wav = selectionOnly && s.selection
      ? sess.encodeSelectionWav(s.selection.start, s.selection.end, s.bitDepth)
      : sess.encodeWorkingWav(undefined, s.bitDepth);
    if (!wav) {
      s.status = "Nothing to save (check the selection).";
      await reload();
      return;
    }
    const suffix = selectionOnly ? "selection" : "processed";
    const fileName = `${(s.source.originalFileName ?? s.source.fileName).replace(/\.[^.]+$/, "")}-${suffix}.wav`;
    const repo = new EvidenceRepository(db());
    const derived = await repo.createDerived({
      sourceId: s.source.id,
      mediaType: "audio",
      title: `${s.source.title} — ${selectionOnly ? "selection" : "processed"}`,
      fileName,
      data: new Blob([wav], { type: "audio/wav" }),
    });
    const operations = sess.operationLog.map((op) => `${op.kind}${op.range ? ` (${op.range.start.toFixed(2)}–${op.range.end.toFixed(2)}s)` : ""}`).join("; ");
    await db().evidence.put({
      ...derived,
      originalFileName: fileName,
      sourceDescription: `Derived from ${s.source.originalFileName ?? s.source.fileName}`,
      importedAt: Date.now(),
      verificationStatus: "verified",
      verifiedAt: Date.now(),
      verificationDetail: "Written from the in-memory analysis copy and hashed on write.",
      roomId: s.source.roomId ?? null,
      captureTimestamp: Date.now(),
      captureTimestampSource: "investigator",
      derivationMethod: selectionOnly ? "audio-selection-export" : "audio-processing",
      derivationParameters: {
        sourceEvidenceId: s.source.id,
        operations: operations || "none",
        bitDepth: s.bitDepth,
        gainDB: s.gainDB,
        lowGain: s.lowGain,
        midGain: s.midGain,
        highGain: s.highGain,
        noiseAmount: s.noiseAmount,
        speedFactor: s.speedFactor,
        selectionOnly,
      },
      notes: `Analyst notes: ${notes || "(none)"} • Source: ${s.source.originalFileName ?? s.source.fileName} • Operations: ${operations || "none"}`,
    });
    await new AuditService(db()).record("evidenceProcessed", "Audio derivative saved from the analysis workspace.", {
      caseId,
      affectedRecordId: derived.id,
      metadata: { parentId: s.source.id, selectionOnly, operations: sess.operationLog.length },
    });
    s.status = `Saved derivative "${fileName}" — the original remains unchanged.`;
    await reload();
  };
  onDelegate(container, "click", "#aa-save-derivative", () => void saveDerivative(false));
  onDelegate(container, "click", "#aa-save-selection", () => void saveDerivative(true));
}

/** Release playback URLs when leaving the view. */
export function releaseAudioAnalysisUrls(container: HTMLElement): void {
  const s = ui.get(container);
  if (s) releaseUrls(s);
}
