/**
 * Audio analysis engine (TPI-V2-WEB-010 §8/§9, Phase 010B).
 *
 * Port of `Core/Audio/PPAudioAnalysisCoordinator.swift` +
 * `PPAudioEditDecisionList.swift`. Bin counts, window sizes, dB floors and the
 * anomaly detector's thresholds are taken from the original source.
 *
 * Integrity rules enforced here:
 *  - the decoded source samples are held once and never mutated;
 *  - every operation works on a copy;
 *  - undo/redo keep full snapshots so an investigator can always return to the
 *    exact starting material;
 *  - the EDL records kind, range, timestamp and note for every operation;
 *  - saving produces a DERIVATIVE (never overwrites the original).
 */
import {
  amplify,
  changeSpeed,
  encodeWavPcm,
  type WavBitDepth,
  equalizer,
  normalize,
  reduceNoise,
  resample,
  reverse,
} from "./audioDsp";

/** `SpectrogramConfig` defaults (PPAudioTypes). */
export const SPECTROGRAM_CONFIG = {
  fftSize: 2048,
  overlap: 0.75,
  minFrequency: 20,
  maxFrequency: 12_000,
  floorDB: -80,
  ceilingDB: 0,
} as const;

export const WAVEFORM_BINS = 360;
export const SPECTRUM_WINDOW = 2048;
export const ANOMALY_DEFAULT_THRESHOLD_DB = -22.0;
export const ANOMALY_DEFAULT_MIN_SPACING_S = 0.45;

/** `PPAudioEditDecisionList.OperationKind`. */
export type OperationKind =
  | "cut"
  | "delete"
  | "paste"
  | "reverse"
  | "amplify"
  | "normalize"
  | "equalizer"
  | "noiseReduction"
  | "speed";

export interface EditOperation {
  id: string;
  kind: OperationKind;
  range: { start: number; end: number } | null;
  timestamp: number;
  note: string;
}

export interface LoadedAudio {
  fileName: string;
  sampleRate: number;
  durationSeconds: number;
  channels: number;
  /** Source samples — treated as immutable by every operation. */
  samples: Float32Array;
}

/* ----------------------------------- FFT ---------------------------------- */

/**
 * Iterative in-place radix-2 complex FFT (Cooley–Tukey). Deterministic and
 * dependency-free; used for the spectrum and spectrogram exactly like the
 * original's vDSP path.
 */
export function fft(re: Float64Array, im: Float64Array): void {
  const n = re.length;
  if (n <= 1 || (n & (n - 1)) !== 0) throw new Error("FFT length must be a power of two.");
  // Bit-reversal permutation
  for (let i = 1, j = 0; i < n; i += 1) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j]!, re[i]!];
      [im[i], im[j]] = [im[j]!, im[i]!];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const angle = (-2 * Math.PI) / len;
    const wRe = Math.cos(angle);
    const wIm = Math.sin(angle);
    for (let i = 0; i < n; i += len) {
      let curRe = 1;
      let curIm = 0;
      for (let k = 0; k < len / 2; k += 1) {
        const uRe = re[i + k] ?? 0;
        const uIm = im[i + k] ?? 0;
        const vRe = (re[i + k + len / 2] ?? 0) * curRe - (im[i + k + len / 2] ?? 0) * curIm;
        const vIm = (re[i + k + len / 2] ?? 0) * curIm + (im[i + k + len / 2] ?? 0) * curRe;
        re[i + k] = uRe + vRe;
        im[i + k] = uIm + vIm;
        re[i + k + len / 2] = uRe - vRe;
        im[i + k + len / 2] = uIm - vIm;
        const nextRe = curRe * wRe - curIm * wIm;
        curIm = curRe * wIm + curIm * wRe;
        curRe = nextRe;
      }
    }
  }
}

/** Hann window (matches the original's pre-FFT taper). */
function hannWindow(size: number): Float64Array {
  const w = new Float64Array(size);
  for (let i = 0; i < size; i += 1) w[i] = 0.5 * (1 - Math.cos((2 * Math.PI * i) / (size - 1)));
  return w;
}

const hannCache = new Map<number, Float64Array>();
function hann(size: number): Float64Array {
  let w = hannCache.get(size);
  if (!w) {
    w = hannWindow(size);
    hannCache.set(size, w);
  }
  return w;
}

/** Magnitude spectrum in dB from a sample window. */
export function magnitudeSpectrum(window: Float32Array, normalizeOutput = true): Float64Array {
  const n = window.length;
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  const w = hann(n);
  for (let i = 0; i < n; i += 1) re[i] = (window[i] ?? 0) * (w[i] ?? 0);
  fft(re, im);
  const half = n / 2;
  const out = new Float64Array(half);
  let peak = 0;
  for (let k = 0; k < half; k += 1) {
    const mag = Math.sqrt((re[k] ?? 0) ** 2 + (im[k] ?? 0) ** 2) / half;
    out[k] = mag;
    if (mag > peak) peak = mag;
  }
  return out.map((v) => {
    const db = 20 * Math.log10(Math.max(v, 1e-7));
    return normalizeOutput && peak > 0 ? db + 20 * Math.log10(1 / Math.max(peak, 1e-7)) * 0 : db;
  });
}

/* ------------------------------- analysis API ------------------------------- */

export interface SpectrogramResult {
  /** Rows are frequency bins (log-spaced), columns are time frames. */
  data: Float64Array[];
  frames: number;
  bins: number;
  frameSeconds: number;
  maxDB: number;
  minDB: number;
}

export class AudioAnalysisSession {
  private source: LoadedAudio;
  private working: Float32Array;
  private undoStack: Float32Array[] = [];
  private redoStack: Float32Array[] = [];
  private clipboard: Float32Array | null = null;
  private log: EditOperation[] = [];

  constructor(loaded: LoadedAudio) {
    this.source = loaded;
    this.working = new Float32Array(loaded.samples);
  }

  get fileName(): string {
    return this.source.fileName;
  }
  get sampleRate(): number {
    return this.source.sampleRate;
  }
  get sourceDuration(): number {
    return this.source.samples.length / this.source.sampleRate;
  }
  get duration(): number {
    return this.working.length / this.source.sampleRate;
  }
  get operationLog(): EditOperation[] {
    return [...this.log];
  }
  get sourceSamples(): Float32Array {
    return this.source.samples;
  }
  get currentSamples(): Float32Array {
    return this.working;
  }
  get isModified(): boolean {
    return this.log.length > 0;
  }
  canUndo(): boolean {
    return this.undoStack.length > 0;
  }
  canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  private snapshotForUndo(): void {
    this.undoStack.push(new Float32Array(this.working));
    this.redoStack = [];
  }

  private note(kind: OperationKind, range: { start: number; end: number } | null, text: string): void {
    this.log.push({ id: `${Date.now()}-${this.log.length}`, kind, range, timestamp: Date.now(), note: text });
  }

  private sampleIndex(time: number): number {
    return Math.max(0, Math.min(this.working.length, Math.round(time * this.source.sampleRate)));
  }

  private sampleRange(start?: number | null, end?: number | null): { from: number; to: number } | null {
    if (start === null || start === undefined || end === null || end === undefined) return null;
    const from = Math.min(this.sampleIndex(start), this.sampleIndex(end));
    const to = Math.max(this.sampleIndex(start), this.sampleIndex(end));
    if (to <= from) return null;
    return { from, to };
  }

  /* ------------------------------ operations ------------------------------ */

  copy(start: number, end: number): boolean {
    const range = this.sampleRange(start, end);
    if (!range) return false;
    this.clipboard = this.working.slice(range.from, range.to);
    return true;
  }

  cut(start: number, end: number): boolean {
    if (!this.copy(start, end)) return false;
    return this.delete(start, end);
  }

  delete(start: number, end: number): boolean {
    const range = this.sampleRange(start, end);
    if (!range) return false;
    this.snapshotForUndo();
    const out = new Float32Array(this.working.length - (range.to - range.from));
    out.set(this.working.subarray(0, range.from), 0);
    out.set(this.working.subarray(range.to), range.from);
    this.working = out;
    this.note("delete", { start, end }, `Deleted ${(end - start).toFixed(2)}s`);
    return true;
  }

  paste(at: number): boolean {
    if (!this.clipboard) return false;
    this.snapshotForUndo();
    const atIdx = this.sampleIndex(at);
    const out = new Float32Array(this.working.length + this.clipboard.length);
    out.set(this.working.subarray(0, atIdx), 0);
    out.set(this.clipboard, atIdx);
    out.set(this.working.subarray(atIdx), atIdx + this.clipboard.length);
    this.working = out;
    this.note("paste", { start: at, end: at }, `Pasted at ${at.toFixed(2)}s`);
    return true;
  }

  reverse(start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    this.snapshotForUndo();
    if (!range) {
      this.working = reverse(this.working);
      this.note("reverse", null, "Reversed entire recording");
      return true;
    }
    const segment = reverse(this.working.slice(range.from, range.to));
    this.working.set(segment, range.from);
    this.note("reverse", { start: start!, end: end! }, `Reversed ${start!.toFixed(2)}–${end!.toFixed(2)}s`);
    return true;
  }

  applyAmplify(gainDB: number, start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    this.snapshotForUndo();
    if (!range) {
      this.working = amplify(this.working, gainDB);
      this.note("amplify", null, `Amplify ${gainDB.toFixed(1)} dB (whole file)`);
      return true;
    }
    this.working.set(amplify(this.working.slice(range.from, range.to), gainDB), range.from);
    this.note("amplify", { start: start!, end: end! }, `Amplify ${gainDB.toFixed(1)} dB (${start!.toFixed(2)}–${end!.toFixed(2)}s)`);
    return true;
  }

  applyNormalize(targetPeak = 0.95, start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    this.snapshotForUndo();
    if (!range) {
      this.working = normalize(this.working, targetPeak);
      this.note("normalize", null, `Normalize to ${targetPeak.toFixed(2)} peak (whole file)`);
      return true;
    }
    this.working.set(normalize(this.working.slice(range.from, range.to), targetPeak), range.from);
    this.note("normalize", { start: start!, end: end! }, `Normalize to ${targetPeak.toFixed(2)} peak`);
    return true;
  }

  applyEqualizer(lowGain: number, midGain: number, highGain: number, start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    this.snapshotForUndo();
    const params = `low ${lowGain.toFixed(2)} / mid ${midGain.toFixed(2)} / high ${highGain.toFixed(2)}`;
    if (!range) {
      this.working = equalizer(this.working, this.source.sampleRate, lowGain, midGain, highGain);
      this.note("equalizer", null, `Equalizer ${params} (whole file)`);
      return true;
    }
    this.working.set(
      equalizer(this.working.slice(range.from, range.to), this.source.sampleRate, lowGain, midGain, highGain),
      range.from,
    );
    this.note("equalizer", { start: start!, end: end! }, `Equalizer ${params}`);
    return true;
  }

  applyNoiseReduction(amount: number, start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    this.snapshotForUndo();
    if (!range) {
      this.working = reduceNoise(this.working, amount);
      this.note("noiseReduction", null, `Noise reduction ${amount.toFixed(2)} (whole file)`);
      return true;
    }
    this.working.set(reduceNoise(this.working.slice(range.from, range.to), amount), range.from);
    this.note("noiseReduction", { start: start!, end: end! }, `Noise reduction ${amount.toFixed(2)}`);
    return true;
  }

  applySpeed(factor: number, start?: number | null, end?: number | null): boolean {
    const range = this.sampleRange(start, end);
    if (factor <= 0.05) return false;
    this.snapshotForUndo();
    if (!range) {
      this.working = changeSpeed(this.working, factor);
      this.note("speed", null, `Speed ×${factor.toFixed(2)} (whole file)`);
      return true;
    }
    this.working.set(changeSpeed(this.working.slice(range.from, range.to), factor), range.from);
    this.note("speed", { start: start!, end: end! }, `Speed ×${factor.toFixed(2)}`);
    return true;
  }

  undo(): boolean {
    const previous = this.undoStack.pop();
    if (!previous) return false;
    this.redoStack.push(new Float32Array(this.working));
    this.working = previous;
    return true;
  }

  redo(): boolean {
    const next = this.redoStack.pop();
    if (!next) return false;
    this.undoStack.push(new Float32Array(this.working));
    this.working = next;
    return true;
  }

  clearOperations(): void {
    this.undoStack.push(new Float32Array(this.working));
    this.redoStack = [];
    this.working = new Float32Array(this.source.samples);
    this.log = [];
  }

  /* ------------------------------- analysis ------------------------------- */

  /**
   * `buildWaveformDB` — 360 bins of peak dBFS across the recording,
   * matching the original's default bin count.
   */
  waveformDB(bins = WAVEFORM_BINS, samples: Float32Array = this.working): number[] {
    const data = samples;
    if (data.length === 0) return new Array(bins).fill(-80);
    const perBin = Math.max(1, Math.floor(data.length / bins));
    const out: number[] = [];
    for (let b = 0; b < bins; b += 1) {
      const from = b * perBin;
      const to = Math.min(data.length, from + perBin);
      let peak = 0;
      for (let i = from; i < to; i += 1) peak = Math.max(peak, Math.abs(data[i] ?? 0));
      out.push(20 * Math.log10(Math.max(peak, 1e-5)));
    }
    return out;
  }

  /** Windowed dBFS values around a time position (`waveformSnapshot`). */
  waveformSnapshot(at: number, windowSeconds = 4.0, bins = WAVEFORM_BINS): number[] {
    const half = windowSeconds / 2;
    const from = this.sampleIndex(Math.max(0, at - half));
    const to = this.sampleIndex(Math.min(this.duration, at + half));
    if (to <= from) return new Array(bins).fill(-80);
    return this.waveformDB(bins, this.working.slice(from, to));
  }

  /** `spectrumSnapshot(at:)` — 2048-sample window. */
  spectrumSnapshot(at: number, preferredWindowSize = SPECTRUM_WINDOW): number[] {
    const size = preferredWindowSize;
    const centre = this.sampleIndex(at);
    const from = Math.max(0, centre - Math.floor(size / 2));
    const window = new Float32Array(size);
    for (let i = 0; i < size; i += 1) window[i] = this.working[from + i] ?? 0;
    return Array.from(magnitudeSpectrum(window));
  }

  /** `spectrogramSnapshot` — 2048 FFT with 75 % overlap, 20 Hz–12 kHz log bins. */
  spectrogramSnapshot(config = SPECTROGRAM_CONFIG, maxFrames = 400): SpectrogramResult {
    const { fftSize, overlap, minFrequency, maxFrequency, floorDB, ceilingDB } = config;
    const hop = Math.max(1, Math.round(fftSize * (1 - overlap)));
    const totalFrames = Math.max(1, Math.floor((this.working.length - fftSize) / hop) + 1);
    const stride = Math.max(1, Math.ceil(totalFrames / maxFrames));
    const bins = 128;
    const frameIndices: number[] = [];
    for (let f = 0; f < totalFrames; f += stride) frameIndices.push(f);

    // Pre-compute the log-frequency bin edges once.
    const logMin = Math.log10(minFrequency);
    const logMax = Math.log10(maxFrequency);
    const half = fftSize / 2;
    const edges = Array.from({ length: bins }, (_, bin) => {
      const fLow = 10 ** (logMin + ((logMax - logMin) * bin) / bins);
      const fHigh = 10 ** (logMin + ((logMax - logMin) * (bin + 1)) / bins);
      const kFrom = Math.max(1, Math.floor((fLow / this.source.sampleRate) * fftSize));
      const kTo = Math.min(half - 1, Math.max(kFrom, Math.ceil((fHigh / this.source.sampleRate) * fftSize)));
      return { kFrom, kTo };
    });

    // Rows = frequency bins, columns = time frames (spectrogram orientation).
    const data: Float64Array[] = Array.from({ length: bins }, () => new Float64Array(frameIndices.length));
    const window = new Float32Array(fftSize);
    for (let col = 0; col < frameIndices.length; col += 1) {
      const offset = (frameIndices[col] as number) * hop;
      for (let i = 0; i < fftSize; i += 1) window[i] = this.working[offset + i] ?? 0;
      const mags = magnitudeSpectrum(window, false);
      for (let bin = 0; bin < bins; bin += 1) {
        const { kFrom, kTo } = edges[bin] as { kFrom: number; kTo: number };
        let peak = 0;
        for (let k = kFrom; k <= kTo; k += 1) peak = Math.max(peak, mags[k] ?? 0);
        const db = 20 * Math.log10(Math.max(peak, 1e-7));
        data[bin]![col] = Math.max(floorDB, Math.min(ceilingDB, db));
      }
    }

    return {
      data,
      frames: frameIndices.length,
      bins,
      frameSeconds: (hop * stride) / this.source.sampleRate,
      maxDB: ceilingDB,
      minDB: floorDB,
    };
  }

  /** `detectAnomalies` — threshold detector over real samples (not a classifier). */
  detectAnomalies(thresholdDB = ANOMALY_DEFAULT_THRESHOLD_DB, minSpacingSeconds = ANOMALY_DEFAULT_MIN_SPACING_S): number[] {
    const data = this.working;
    if (data.length === 0) return [];
    const windowSize = 1024;
    const hop = 256;
    const times: number[] = [];
    let lastHit = -Infinity;
    for (let offset = 0; offset + windowSize <= data.length; offset += hop) {
      let sumSquares = 0;
      for (let i = 0; i < windowSize; i += 1) {
        const v = data[offset + i] ?? 0;
        sumSquares += v * v;
      }
      const db = 20 * Math.log10(Math.max(Math.sqrt(sumSquares / windowSize), 1e-7));
      const t = offset / this.source.sampleRate;
      if (db >= thresholdDB && t - lastHit >= minSpacingSeconds) {
        times.push(t);
        lastHit = t;
      }
    }
    return times;
  }

  /** `spectrumTopFrequencies(limit:)` — strongest bins at a position. */
  spectrumTopFrequencies(at: number, limit = 6): Array<{ freq: number; magnitude: number }> {
    const mags = this.spectrumSnapshot(at);
    const binHz = this.source.sampleRate / (mags.length * 2);
    return mags
      .map((mag, k) => ({ freq: k * binHz, magnitude: mag }))
      .filter((m) => m.freq >= 20 && m.freq <= 12_000)
      .sort((a, b) => b.magnitude - a.magnitude)
      .slice(0, limit);
  }

  /** Peak dBFS of a range (used for the selection readout). */
  peakDBFSIn(start: number, end: number): number {
    const range = this.sampleRange(start, end);
    const data = range ? this.working.subarray(range.from, range.to) : this.working;
    let peak = 0;
    for (let i = 0; i < data.length; i += 1) peak = Math.max(peak, Math.abs(data[i] ?? 0));
    return 20 * Math.log10(Math.max(peak, 1e-5));
  }

  /**
   * Encode the working copy as WAV. Bit depth defaults to 16 but supports the
   * original's 8/16/24/32 options (ExportOptions.bitDepth).
   */
  encodeWorkingWav(targetSampleRate?: number, bitDepth: WavBitDepth = 16): ArrayBuffer {
    const samples = targetSampleRate && Math.abs(targetSampleRate - this.source.sampleRate) > 0.01
      ? resample(this.working, this.source.sampleRate, targetSampleRate)
      : this.working;
    return encodeWavPcm(samples, targetSampleRate ?? this.source.sampleRate, 1, bitDepth);
  }

  /** Encode the current selection as WAV at the requested bit depth. */
  encodeSelectionWav(start: number, end: number, bitDepth: WavBitDepth = 16): ArrayBuffer | null {
    const range = this.sampleRange(start, end);
    if (!range) return null;
    return encodeWavPcm(this.working.slice(range.from, range.to), this.source.sampleRate, 1, bitDepth);
  }
}

/** Decode an audio file into mono samples for analysis. */
export async function loadAudioForAnalysis(file: File): Promise<LoadedAudio> {
  const bytes = await file.arrayBuffer();
  // WAV is decoded in-process (deterministic, and works for our own exports).
  const isWav = file.type.includes("wav") || file.name.toLowerCase().endsWith(".wav");
  if (isWav) {
    const { samples, sampleRate, channels } = decodeWavBytes(bytes);
    return { fileName: file.name, sampleRate, durationSeconds: samples.length / sampleRate, channels, samples };
  }
  // Other containers: use the browser decoder (no transcoding of the original —
  // this is an in-memory analysis copy only).
  const Ctor: typeof AudioContext | undefined =
    typeof AudioContext !== "undefined" ? AudioContext : (globalThis as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!Ctor) throw new Error("This browser cannot decode audio for analysis.");
  const ctx = new Ctor();
  try {
    const decoded = await ctx.decodeAudioData(bytes.slice(0));
    const channels = decoded.numberOfChannels;
    const length = decoded.length;
    const mixed = new Float32Array(length);
    for (let c = 0; c < channels; c += 1) {
      const data = decoded.getChannelData(c);
      for (let i = 0; i < length; i += 1) mixed[i] = (mixed[i] ?? 0) + (data[i] ?? 0) / channels;
    }
    return { fileName: file.name, sampleRate: decoded.sampleRate, durationSeconds: decoded.duration, channels, samples: mixed };
  } finally {
    void ctx.close().catch(() => undefined);
  }
}

function decodeWavBytes(buffer: ArrayBuffer): { samples: Float32Array; sampleRate: number; channels: number } {
  // Imported lazily to keep this module's public surface focused.
  const view = new DataView(buffer);
  const ascii = (o: number, len: number) => {
    let s = "";
    for (let i = 0; i < len; i += 1) s += String.fromCharCode(view.getUint8(o + i));
    return s;
  };
  if (ascii(0, 4) !== "RIFF" || ascii(8, 4) !== "WAVE") throw new Error("Not a RIFF/WAVE file.");
  let offset = 12;
  let channels = 1;
  let sampleRate = 44_100;
  let bits = 16;
  let format = 1;
  let dataStart = -1;
  let dataLength = 0;
  while (offset + 8 <= view.byteLength) {
    const id = ascii(offset, 4);
    const size = view.getUint32(offset + 4, true);
    const body = offset + 8;
    if (id === "fmt ") {
      format = view.getUint16(body, true);
      channels = view.getUint16(body + 2, true);
      sampleRate = view.getUint32(body + 4, true);
      bits = view.getUint16(body + 14, true);
    } else if (id === "data") {
      dataStart = body;
      dataLength = Math.min(size, view.byteLength - body);
      break;
    }
    offset = body + size + (size % 2);
  }
  if (dataStart < 0) throw new Error("WAV file has no data chunk.");
  const bytesPerSample = bits / 8;
  const frames = Math.floor(dataLength / (bytesPerSample * channels));
  const samples = new Float32Array(frames);
  for (let f = 0; f < frames; f += 1) {
    let sum = 0;
    for (let c = 0; c < channels; c += 1) {
      const o = dataStart + (f * channels + c) * bytesPerSample;
      let v = 0;
      if (format === 3 && bits === 32) v = view.getFloat32(o, true);
      else if (bits === 8) {
        const unsigned = view.getUint8(o);
        v = unsigned >= 128 ? (unsigned - 128) / 127 : (unsigned - 128) / 128;
      } else if (bits === 32) v = view.getInt32(o, true) / 0x8000_0000;
      else if (bits === 24) {
        let raw = view.getUint8(o) | (view.getUint8(o + 1) << 8) | (view.getUint8(o + 2) << 16);
        if (raw & 0x80_0000) raw |= ~0xff_ffff;
        v = raw / 0x80_0000;
      } else v = view.getInt16(o, true) / 0x8000;
      sum += v;
    }
    samples[f] = sum / channels;
  }
  return { samples, sampleRate, channels };
}
