/**
 * Audio DSP (TPI-V2-WEB-010 §8/§9, Phase 010B).
 *
 * Verbatim port of `Core/Audio/PPAudioDSP.swift`. Every algorithm, constant and
 * clamp is identical to the original so browser analysis matches the iPad
 * application's processing exactly. Pure functions — no side effects, fully
 * unit-testable.
 *
 * Processing NEVER modifies source media: callers operate on in-memory copies
 * and, if they persist a result, create a separately identified derivative.
 */

/** Original clamp: `min(1, max(-1, x))`. */
export function clamp(x: number): number {
  return Math.min(1, Math.max(-1, x));
}

/** `reverse` */
export function reverse(input: Float32Array): Float32Array {
  const out = new Float32Array(input.length);
  for (let i = 0; i < input.length; i += 1) out[i] = input[input.length - 1 - i] ?? 0;
  return out;
}

/** `amplify(db:)` — linear gain from dB, clamped per sample. */
export function amplify(input: Float32Array, gainDB: number): Float32Array {
  const gain = 10 ** (gainDB / 20);
  const out = new Float32Array(input.length);
  for (let i = 0; i < input.length; i += 1) out[i] = clamp((input[i] ?? 0) * gain);
  return out;
}

/** `normalize(targetPeak: 0.95)` — returns input untouched below the 0.00001 floor. */
export function normalize(input: Float32Array, targetPeak = 0.95): Float32Array {
  let peak = 0;
  for (let i = 0; i < input.length; i += 1) peak = Math.max(peak, Math.abs(input[i] ?? 0));
  if (peak <= 0.00001) return new Float32Array(input);
  const gain = targetPeak / peak;
  const out = new Float32Array(input.length);
  for (let i = 0; i < input.length; i += 1) out[i] = clamp((input[i] ?? 0) * gain);
  return out;
}

/** `changeSpeed(factor:)` — linear interpolation resample; factor ≤ 0.05 rejected. */
export function changeSpeed(input: Float32Array, factor: number): Float32Array {
  if (!Number.isFinite(factor) || factor <= 0.05) return new Float32Array(input);
  const outCount = Math.max(1, Math.round(input.length / factor));
  if (input.length <= 1) {
    const out = new Float32Array(outCount);
    out.fill(input[0] ?? 0);
    return out;
  }
  const out = new Float32Array(outCount);
  for (let i = 0; i < outCount; i += 1) {
    const srcPos = i * factor;
    const a = Math.min(input.length - 1, Math.max(0, Math.floor(srcPos)));
    const b = Math.min(input.length - 1, a + 1);
    const t = srcPos - a;
    const va = input[a] ?? 0;
    const vb = input[b] ?? 0;
    out[i] = clamp(va + (vb - va) * t);
  }
  return out;
}

/** `reduceNoise(amount:)` — 15th-percentile noise floor gate. */
export function reduceNoise(input: Float32Array, amount: number): Float32Array {
  if (input.length === 0) return new Float32Array(0);
  const magnitudes = Array.from(input, (v) => Math.abs(v)).sort((a, b) => a - b);
  const idx = Math.max(0, Math.min(magnitudes.length - 1, Math.floor(magnitudes.length * 0.15)));
  const floor = Math.max(0.0005, magnitudes[idx] ?? 0);
  const clampedAmount = Math.max(0, Math.min(amount, 1));
  const threshold = floor * (1 + clampedAmount);
  const out = new Float32Array(input);
  for (let i = 0; i < out.length; i += 1) {
    if (Math.abs(out[i] ?? 0) < threshold) out[i] = (out[i] ?? 0) * (1 - 0.75 * clampedAmount);
  }
  return out;
}

/** One-pole low pass (original cutoff 250 Hz for the low band). */
function onePoleLowPass(signal: Float32Array, cutoffHz: number, sampleRate: number): Float32Array {
  if (signal.length === 0) return new Float32Array(0);
  const dt = 1 / sampleRate;
  const rc = 1 / (2 * Math.PI * cutoffHz);
  const alpha = dt / (rc + dt);
  const out = new Float32Array(signal.length);
  out[0] = signal[0] ?? 0;
  for (let i = 1; i < signal.length; i += 1) {
    out[i] = (out[i - 1] ?? 0) + alpha * ((signal[i] ?? 0) - (out[i - 1] ?? 0));
  }
  return out;
}

/** One-pole high pass (original cutoff 2500 Hz for the high band). */
function onePoleHighPass(signal: Float32Array, cutoffHz: number, sampleRate: number): Float32Array {
  if (signal.length === 0) return new Float32Array(0);
  const dt = 1 / sampleRate;
  const rc = 1 / (2 * Math.PI * cutoffHz);
  const alpha = rc / (rc + dt);
  const out = new Float32Array(signal.length);
  out[0] = signal[0] ?? 0;
  for (let i = 1; i < signal.length; i += 1) {
    out[i] = alpha * ((out[i - 1] ?? 0) + (signal[i] ?? 0) - (signal[i - 1] ?? 0));
  }
  return out;
}

/**
 * `equalizer(low:mid:high:)` — original band split: low ≤ 250 Hz,
 * high ≥ 2500 Hz, mid = remainder.
 */
export function equalizer(
  input: Float32Array,
  sampleRate: number,
  lowGain: number,
  midGain: number,
  highGain: number,
): Float32Array {
  if (input.length === 0) return new Float32Array(0);
  const low = onePoleLowPass(input, 250, sampleRate);
  const high = onePoleHighPass(input, 2500, sampleRate);
  const out = new Float32Array(input.length);
  for (let i = 0; i < input.length; i += 1) {
    const mid = (input[i] ?? 0) - (low[i] ?? 0) - (high[i] ?? 0);
    out[i] = clamp((low[i] ?? 0) * lowGain + mid * midGain + (high[i] ?? 0) * highGain);
  }
  return out;
}

/** `PPAudioRenderEngine.resample` — linear interpolation to a target rate. */
export function resample(samples: Float32Array, sourceRate: number, targetRate: number): Float32Array {
  if (samples.length === 0) return new Float32Array(0);
  if (Math.abs(sourceRate - targetRate) <= 0.01) return new Float32Array(samples);
  const outCount = Math.max(1, Math.round((samples.length * targetRate) / sourceRate));
  const out = new Float32Array(outCount);
  for (let i = 0; i < outCount; i += 1) {
    const srcPos = (i * sourceRate) / targetRate;
    const a = Math.floor(srcPos);
    const b = Math.min(samples.length - 1, a + 1);
    const t = srcPos - a;
    const va = samples[Math.min(Math.max(0, a), samples.length - 1)] ?? 0;
    const vb = samples[Math.min(Math.max(0, b), samples.length - 1)] ?? 0;
    out[i] = va + (vb - va) * t;
  }
  return out;
}

/* --------------------------------- WAV I/O -------------------------------- */

/**
 * 16-bit PCM WAV encoder — same layout the original `writeWav` produced
 * (RIFF/WAVE/fmt/data, little-endian, mono by default).
 * Used for saving processed derivatives; source files are never rewritten.
 */
export function encodeWavPcm16(samples: Float32Array, sampleRate: number, channels = 1): ArrayBuffer {
  const bytesPerSample = 2;
  const dataBytes = samples.length * bytesPerSample;
  const buffer = new ArrayBuffer(44 + dataBytes);
  const view = new DataView(buffer);
  let offset = 0;
  const ascii = (s: string) => {
    for (const ch of s) view.setUint8(offset++, ch.charCodeAt(0));
  };
  const le16 = (v: number) => {
    view.setUint16(offset, v, true);
    offset += 2;
  };
  const le32 = (v: number) => {
    view.setUint32(offset, v, true);
    offset += 4;
  };
  ascii("RIFF");
  le32(36 + dataBytes);
  ascii("WAVE");
  ascii("fmt ");
  le32(16);
  le16(1); // PCM
  le16(channels);
  le32(sampleRate);
  le32(sampleRate * channels * bytesPerSample); // byte rate
  le16(channels * bytesPerSample); // block align
  le16(16); // bit depth
  ascii("data");
  le32(dataBytes);
  for (let i = 0; i < samples.length; i += 1) {
    const v = Math.max(-1, Math.min(1, samples[i] ?? 0));
    view.setInt16(offset, v < 0 ? v * 0x8000 : v * 0x7fff, true);
    offset += 2;
  }
  return buffer;
}

/**
 * Multi-bit-depth PCM WAV encoder — the original `writeWav` supports
 * 8/16/24/32-bit (`[8, 16, 24, 32].contains(bitDepth) ? bitDepth : 16`), so the
 * browser implements the same set with the same header maths
 * (`blockAlign = ch × bytesPerSample`, `byteRate = rate × ch × bytesPerSample`).
 * 24-bit is a real, selectable original option (TPI-V2-WEB-010G §16).
 */
export type WavBitDepth = 8 | 16 | 24 | 32;

/** Sample rate clamp from the original ExportOptions handling. */
export const WAV_MIN_SAMPLE_RATE = 6_000;
export const WAV_MAX_SAMPLE_RATE = 192_000;

/** Original validation: only 8/16/24/32 are accepted; anything else becomes 16. */
export function normaliseBitDepth(bitDepth: number): WavBitDepth {
  return ([8, 16, 24, 32] as number[]).includes(bitDepth) ? (bitDepth as WavBitDepth) : 16;
}

export function normaliseSampleRate(sampleRate: number): number {
  return Math.max(WAV_MIN_SAMPLE_RATE, Math.min(WAV_MAX_SAMPLE_RATE, sampleRate));
}

export function normaliseChannels(channels: number): number {
  return Math.max(1, Math.min(2, channels));
}

/** Quantise one float sample to the given bit depth (matching Swift rounding/clipping). */
export function quantiseSample(value: number, bitDepth: WavBitDepth): number {
  const v = Math.max(-1, Math.min(1, value));
  const roundAwayFromZero = (x: number): number => x < 0 ? -Math.round(-x) : Math.round(x);
  switch (bitDepth) {
    case 8:
      // Original UInt8 PCM mapping: Int(((sample + 1) * 0.5) * 255), truncated.
      return Math.max(0, Math.min(255, Math.trunc(((v + 1) * 0.5) * 255)));
    case 24:
      return roundAwayFromZero(v * 0x7f_ffff);
    case 32:
      return roundAwayFromZero(v * 0x7fff_ffff);
    case 16:
    default:
      return roundAwayFromZero(v * 0x7fff);
  }
}

/**
 * Encode at 8/16/24/32-bit (mono or stereo interleaved). Stereo input is
 * interleaved as `[L, R, L, R, …]`, matching the original writer.
 */
export function encodeWavPcm(samples: Float32Array, sampleRate: number, channels = 1, bitDepth: WavBitDepth = 16): ArrayBuffer {
  const bits = normaliseBitDepth(bitDepth);
  const ch = normaliseChannels(channels);
  const rate = normaliseSampleRate(sampleRate);
  const bytesPerSample = bits / 8;
  const frameCount = Math.floor(samples.length / ch);
  const dataSize = frameCount * ch * bytesPerSample;
  const buffer = new ArrayBuffer(44 + dataSize);
  const view = new DataView(buffer);
  let o = 0;
  const ascii = (str: string) => {
    for (const c of str) view.setUint8(o++, c.charCodeAt(0));
  };
  const le16 = (v: number) => {
    view.setUint16(o, v, true);
    o += 2;
  };
  const le32 = (v: number) => {
    view.setUint32(o, v, true);
    o += 4;
  };
  const le24 = (v: number) => {
    const u = v >>> 0;
    view.setUint8(o++, u & 0xff);
    view.setUint8(o++, (u >> 8) & 0xff);
    view.setUint8(o++, (u >> 16) & 0xff);
  };
  ascii("RIFF");
  le32(36 + dataSize);
  ascii("WAVE");
  ascii("fmt ");
  le32(16);
  le16(1); // PCM
  le16(ch);
  le32(rate);
  le32(rate * ch * bytesPerSample); // byteRate
  le16(ch * bytesPerSample); // blockAlign
  le16(bits);
  ascii("data");
  le32(dataSize);
  for (let f = 0; f < frameCount; f += 1) {
    for (let c = 0; c < ch; c += 1) {
      const q = quantiseSample(samples[f * ch + c] ?? 0, bits);
      if (bits === 8) view.setUint8(o, q), (o += 1);
      else if (bits === 16) view.setInt16(o, q, true), (o += 2);
      else if (bits === 24) le24(q);
      else view.setInt32(o, q, true), (o += 4);
    }
  }
  return buffer;
}

/** Parse 8/16/24/32-bit PCM or IEEE-float WAV into mono float samples. */
export function decodeWav(buffer: ArrayBuffer): { samples: Float32Array; sampleRate: number; channels: number } {
  const view = new DataView(buffer);
  const ascii = (o: number, len: number) => {
    let s = "";
    for (let i = 0; i < len; i += 1) s += String.fromCharCode(view.getUint8(o + i));
    return s;
  };
  if (ascii(0, 4) !== "RIFF" || ascii(8, 4) !== "WAVE") {
    throw new Error("Not a RIFF/WAVE file.");
  }
  let offset = 12;
  let channels = 1;
  let sampleRate = 44_100;
  let bitsPerSample = 16;
  let format = 1;
  let dataStart = -1;
  let dataLength = 0;
  while (offset + 8 <= view.byteLength) {
    const id = ascii(offset, 4);
    const size = view.getUint32(offset + 4, true);
    const body = offset + 8;
    if (id === "fmt ") {
      format = view.getUint16(body, true);
      channels = view.getUint16(body + 2, true);
      sampleRate = view.getUint32(body + 4, true);
      bitsPerSample = view.getUint16(body + 14, true);
    } else if (id === "data") {
      dataStart = body;
      dataLength = Math.min(size, view.byteLength - body);
      break;
    }
    offset = body + size + (size % 2);
  }
  if (dataStart < 0) throw new Error("WAV file has no data chunk.");
  const bytesPerSample = bitsPerSample / 8;
  const frames = Math.floor(dataLength / (bytesPerSample * channels));
  const samples = new Float32Array(frames);
  for (let f = 0; f < frames; f += 1) {
    let sum = 0;
    for (let c = 0; c < channels; c += 1) {
      const o = dataStart + (f * channels + c) * bytesPerSample;
      let v = 0;
      if (format === 3 && bitsPerSample === 32) v = view.getFloat32(o, true);
      else if (bitsPerSample === 8) {
        const unsigned = view.getUint8(o);
        v = unsigned >= 128 ? (unsigned - 128) / 127 : (unsigned - 128) / 128;
      } else if (bitsPerSample === 32) v = view.getInt32(o, true) / 0x8000_0000;
      else if (bitsPerSample === 24) {
        const b0 = view.getUint8(o);
        const b1 = view.getUint8(o + 1);
        const b2 = view.getUint8(o + 2);
        let raw = b0 | (b1 << 8) | (b2 << 16);
        if (raw & 0x80_0000) raw |= ~0xff_ffff;
        v = raw / 0x80_0000;
      } else {
        v = view.getInt16(o, true) / 0x8000;
      }
      sum += v;
    }
    samples[f] = sum / channels;
  }
  return { samples, sampleRate, channels };
}
